//! Gold: `family_document` is 1:1 with the live reference.
//!
//! `tests/fixtures/gold/family_document_v1.json` was generated by
//! `scripts/gold_family_document.py` — census cases render a real PDF and run
//! the reference's own `read_family_document` end to end, kernel cases call
//! the reference's pure readers. The inputs the port consumes travel in the
//! gold (page texts, extracted table grids, bookmarks, PDF title, file stem)
//! so this replays identical input. The volatile `_meta` keys are stripped.
//!
//! The cases pin the traps the reader exists for: the chapter vocabulary's
//! look-alike exclusions (DCC is not a comparator, Trip-Zone is not
//! TrustZone, Message RAM is not sram), instances counted only with page
//! support, the Renesas cover hierarchy (■ sections over bullets over
//! dashes), single-glyph blocks, the count split ("SCI × 4"), the
//! description-paragraph fact reader, the RZ/G includes card, the
//! Item/Description spec list, prose facts that collapse core spellings and
//! take the stated supply over the widest, and GPIO paired with FC-BGA
//! rather than the ballout figure.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    reason = "gold tests assert on their own fixtures"
)]

use std::collections::BTreeMap;
use std::path::PathBuf;

use dw_recon::family_document::{
    bullets, classify_chapter_title, feature, read_chapter_features, read_description_facts,
    read_family_document, read_includes_list, read_instances, read_io_by_package,
    read_item_description_specs, read_prose_facts, split_count, BulletItem, Chapters,
    FamilyDocInput,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/family_document_v1.json")
}

fn gold() -> serde_json::Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

fn pages_of(v: &serde_json::Value) -> BTreeMap<i64, String> {
    v.as_object()
        .unwrap()
        .iter()
        .map(|(k, t)| (k.parse().unwrap(), t.as_str().unwrap().to_string()))
        .collect()
}

fn tables_of(v: &serde_json::Value) -> Vec<dw_recon::family_census::PageTables> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|e| {
            let page = e["page"].as_i64().unwrap();
            let tables = e["tables"]
                .as_array()
                .unwrap()
                .iter()
                .map(|grid| {
                    grid.as_array()
                        .unwrap()
                        .iter()
                        .map(|row| {
                            row.as_array()
                                .unwrap()
                                .iter()
                                .map(|cell| cell.as_str().map(str::to_string))
                                .collect()
                        })
                        .collect()
                })
                .collect();
            dw_recon::family_census::PageTables { page, tables }
        })
        .collect()
}

fn toc_of(v: &serde_json::Value) -> Vec<(i64, String, i64)> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|e| {
            let a = e.as_array().unwrap();
            (
                a[0].as_i64().unwrap(),
                a[1].as_str().unwrap().to_string(),
                a[2].as_i64().unwrap(),
            )
        })
        .collect()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let got: serde_json::Value = match case["kind"].as_str().unwrap() {
            "census" => {
                let input = &case["input"];
                let pages = pages_of(&input["pages"]);
                let tables = tables_of(&input["tables"]);
                let toc = toc_of(&input["toc"]);
                let doc = FamilyDocInput {
                    pages: &pages,
                    tables: &tables,
                    toc: &toc,
                    pdf_title: input["pdf_title"].as_str(),
                    source_stem: input["source_stem"].as_str().unwrap(),
                    page_count: input["page_count"].as_i64().unwrap(),
                    vendor: case["vendor"].as_str(),
                    max_text_pages: case["max_text_pages"].as_u64().map(|n| n as usize),
                };
                let mut row = read_family_document(&doc);
                row.meta.extracted_at = Some(format!("{name}.iso"));
                row.meta.document_sha256 = Some("f".repeat(64));
                row.meta.source_path = Some(format!("/{name}.pdf"));
                let mut got = serde_json::to_value(&row).unwrap();
                let meta = got.get_mut("_meta").unwrap().as_object_mut().unwrap();
                for k in ["extracted_at", "document_sha256", "source_path"] {
                    meta.remove(k);
                }
                got
            }
            "classify_chapter_title" => {
                serde_json::to_value(classify_chapter_title(case["title"].as_str().unwrap()))
                    .unwrap()
            }
            "bullets" => serde_json::to_value(bullets(case["text"].as_str().unwrap())).unwrap(),
            "bullet_items" => {
                let items: Vec<BulletItem> =
                    serde_json::from_value(case["expected"].clone()).unwrap();
                // Compare via the same serialisation the reference emits.
                let _ = items;
                let got = dw_recon::family_document::bullet_items(case["text"].as_str().unwrap());
                serde_json::to_value(got).unwrap()
            }
            "split_count" => {
                let (label, count) = split_count(case["text"].as_str().unwrap());
                serde_json::to_value((label, count)).unwrap()
            }
            "feature" => {
                let row = feature(
                    case["text"].as_str().unwrap(),
                    case["page"].as_i64().unwrap(),
                    case["section"].as_str(),
                    case["level"].as_i64(),
                    case["parent"].as_str(),
                );
                serde_json::to_value(row).unwrap()
            }
            "read_instances" => {
                let pages = pages_of(&case["pages"]);
                serde_json::to_value(read_instances(&pages, case["weak_pages"].as_i64().unwrap()))
                    .unwrap()
            }
            "read_chapter_features" => {
                let pages = pages_of(&case["pages"]);
                let chapters: Chapters = serde_json::from_value(case["chapters"].clone()).unwrap();
                serde_json::to_value(read_chapter_features(
                    &pages,
                    &chapters,
                    case["page_count"].as_i64().unwrap(),
                ))
                .unwrap()
            }
            "read_prose_facts" => {
                let pages = pages_of(&case["pages"]);
                serde_json::to_value(read_prose_facts(
                    &pages,
                    case["max_pages"].as_u64().unwrap() as usize,
                ))
                .unwrap()
            }
            "read_description_facts" => {
                let pages = pages_of(&case["pages"]);
                serde_json::to_value(read_description_facts(
                    &pages,
                    case["max_pages"].as_u64().unwrap() as usize,
                ))
                .unwrap()
            }
            "read_includes_list" => {
                let pages = pages_of(&case["pages"]);
                serde_json::to_value(read_includes_list(
                    &pages,
                    case["max_pages"].as_u64().unwrap() as usize,
                ))
                .unwrap()
            }
            "read_item_description_specs" => {
                let pages = pages_of(&case["pages"]);
                serde_json::to_value(read_item_description_specs(
                    &pages,
                    case["max_pages"].as_u64().unwrap() as usize,
                ))
                .unwrap()
            }
            "read_io_by_package" => {
                let pages = pages_of(&case["pages"]);
                serde_json::to_value(read_io_by_package(&pages)).unwrap()
            }
            other => panic!("unknown gold case kind {other}"),
        };
        assert_eq!(got, case["expected"], "case {name}");
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
